import{_ as t,o as d,c as a,ae as o}from"./chunks/framework.C4zpkcTP.js";const y=JSON.parse('{"title":"PaymentCallback & Status","description":"Field reference for PaymentCallback, PaymentStatusResult, Acknowledgement, CallbackRequest and the PaymentStatus type.","frontmatter":{"title":"PaymentCallback & Status","description":"Field reference for PaymentCallback, PaymentStatusResult, Acknowledgement, CallbackRequest and the PaymentStatus type."},"headers":[],"relativePath":"node-myanmar-payments/references/payment-callback.md","filePath":"node-myanmar-payments/references/payment-callback.md"}'),c={name:"node-myanmar-payments/references/payment-callback.md"};function r(s,e,n,l,u,i){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="paymentcallback-status" tabindex="-1">PaymentCallback &amp; Status <a class="header-anchor" href="#paymentcallback-status" aria-label="Permalink to &quot;PaymentCallback &amp; Status&quot;">​</a></h1><h2 id="paymentcallback" tabindex="-1">PaymentCallback <a class="header-anchor" href="#paymentcallback" aria-label="Permalink to &quot;PaymentCallback&quot;">​</a></h2><p>Returned by every gateway&#39;s <code>handleCallback()</code> (and AYA&#39;s <code>verifyRedirect()</code>) once the signature is verified.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>orderId</code></td><td><code>string</code></td><td>Your order ID</td></tr><tr><td><code>status</code></td><td><code>PaymentStatus</code></td><td>The status mapped onto this package&#39;s statuses</td></tr><tr><td><code>gatewayStatus</code></td><td><code>string</code></td><td>The gateway&#39;s own status value, unmapped</td></tr><tr><td><code>gatewayReference</code></td><td><code>string | undefined</code></td><td>The gateway&#39;s ID for the payment</td></tr><tr><td><code>amount</code></td><td><code>string | undefined</code></td><td>The amount the gateway reports, exactly as it sent it</td></tr><tr><td><code>raw</code></td><td><code>Record&lt;string, unknown&gt;</code></td><td>The verified payload, as plain JavaScript values; JSON numbers are their exact text as <code>string</code>s</td></tr><tr><td><code>acknowledgement</code></td><td><code>Acknowledgement</code></td><td>The response the gateway expects</td></tr><tr><td><code>isSuccessful()</code></td><td><code>boolean</code></td><td><code>status === &#39;successful&#39;</code></td></tr></tbody></table><p>Build one yourself to test your own fulfillment code, with an object: <code>new PaymentCallback({ orderId, status, gatewayStatus, gatewayReference?, amount?, raw?, acknowledgement? })</code>. <code>status</code> takes a <code>PaymentStatus</code> value, and <code>acknowledgement</code> defaults to <code>Acknowledgement.default()</code>.</p><h2 id="acknowledgement" tabindex="-1">Acknowledgement <a class="header-anchor" href="#acknowledgement" aria-label="Permalink to &quot;Acknowledgement&quot;">​</a></h2><p>A class with read-only fields; <code>new Acknowledgement({ status?, body?, headers? })</code> builds one.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>status</code></td><td><code>number</code></td><td>HTTP status, <code>200</code> by default</td></tr><tr><td><code>body</code></td><td><code>string</code></td><td>Response body, e.g. KBZ Pay&#39;s <code>success</code>; empty by default</td></tr><tr><td><code>headers</code></td><td><code>Record&lt;string, string&gt;</code></td><td>Response headers, <code>{ &#39;Content-Type&#39;: &#39;text/plain&#39; }</code> by default</td></tr><tr><td><code>send(res)</code></td><td><code>void</code></td><td>Writes the status, headers and body to a <code>node:http</code> <code>ServerResponse</code> (or Express <code>res</code>) and ends it</td></tr><tr><td><code>toResponse()</code></td><td><code>Response</code></td><td>The acknowledgement as a Fetch API <code>Response</code></td></tr></tbody></table><p><code>Acknowledgement.default()</code> is an empty <code>200</code> with <code>Content-Type: text/plain</code>. Write it with your framework&#39;s response API, see <a href="/node-myanmar-payments/callbacks.html#acknowledging">Acknowledging</a>.</p><h2 id="paymentstatusresult" tabindex="-1">PaymentStatusResult <a class="header-anchor" href="#paymentstatusresult" aria-label="Permalink to &quot;PaymentStatusResult&quot;">​</a></h2><p>Returned by <code>kbz.status()</code>, <code>aya.status()</code> and <code>yoma.status()</code>. A class with read-only fields.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>orderId</code></td><td><code>string | undefined</code></td><td>Your order ID; <code>undefined</code> for Yoma, which returns only the reference</td></tr><tr><td><code>status</code></td><td><code>PaymentStatus</code></td><td>The mapped status</td></tr><tr><td><code>gatewayStatus</code></td><td><code>string</code></td><td>The gateway&#39;s own status value</td></tr><tr><td><code>gatewayReference</code></td><td><code>string | undefined</code></td><td>The gateway&#39;s ID for the payment</td></tr><tr><td><code>amount</code></td><td><code>string | undefined</code></td><td>The amount the gateway reports</td></tr><tr><td><code>raw</code></td><td><code>Record&lt;string, unknown&gt;</code></td><td>The gateway&#39;s response</td></tr><tr><td><code>isSuccessful()</code></td><td><code>boolean</code></td><td><code>status === &#39;successful&#39;</code></td></tr></tbody></table><h2 id="callbackrequest" tabindex="-1">CallbackRequest <a class="header-anchor" href="#callbackrequest" aria-label="Permalink to &quot;CallbackRequest&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Member</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>CallbackRequest.from({ body, headers, query })</code></td><td><code>CallbackRequest</code></td><td>From the raw parts: the body as a <code>string</code>, <code>Buffer</code>, <code>Uint8Array</code> or <code>ArrayBuffer</code>, the headers as an object or <code>[name, value]</code> pairs, the query string as a <code>string</code>, <code>URLSearchParams</code> or an object. All three are optional</td></tr><tr><td><code>CallbackRequest.fromJson(payload, headers?)</code></td><td><code>CallbackRequest</code></td><td>From a decoded payload, encoded as a JSON body</td></tr><tr><td><code>CallbackRequest.fromNodeRequest(req)</code></td><td><code>Promise&lt;CallbackRequest&gt;</code></td><td>From a <code>node:http</code> <code>IncomingMessage</code> (Express <code>req</code>, or Koa <code>ctx.req</code> without a body parser)</td></tr><tr><td><code>CallbackRequest.fromWebRequest(request)</code></td><td><code>Promise&lt;CallbackRequest&gt;</code></td><td>From a Fetch API <code>Request</code>, read from a clone</td></tr><tr><td><code>rawBody</code></td><td><code>Uint8Array</code></td><td>The raw body, exactly as received</td></tr><tr><td><code>body</code></td><td><code>string</code></td><td>The raw body, decoded as UTF-8</td></tr><tr><td><code>headers</code></td><td><code>Record&lt;string, string&gt;</code></td><td>Headers with lowercase names; repeated headers joined with <code>, </code></td></tr><tr><td><code>query</code></td><td><code>Record&lt;string, string&gt;</code></td><td>Query string values (the first of each)</td></tr><tr><td><code>header(name)</code></td><td><code>string | undefined</code></td><td>One header, case-insensitively</td></tr><tr><td><code>parsedBody()</code></td><td><code>Record&lt;string, unknown&gt;</code></td><td>The body decoded as JSON or a form; JSON numbers are their exact text as <code>string</code>s</td></tr><tr><td><code>input()</code></td><td><code>Record&lt;string, unknown&gt;</code></td><td>The body merged over the query string</td></tr><tr><td><code>queryInput()</code></td><td><code>Record&lt;string, unknown&gt;</code></td><td>The query string merged over the body</td></tr></tbody></table><h2 id="paymentstatus" tabindex="-1">PaymentStatus <a class="header-anchor" href="#paymentstatus" aria-label="Permalink to &quot;PaymentStatus&quot;">​</a></h2><p><code>type PaymentStatus = &#39;successful&#39; | &#39;pending&#39; | &#39;failed&#39; | &#39;canceled&#39; | &#39;expired&#39; | &#39;unknown&#39;</code>: statuses are plain strings, and the <code>PaymentStatus</code> object names each value.</p><table tabindex="0"><thead><tr><th>Constant</th><th>Value</th></tr></thead><tbody><tr><td><code>PaymentStatus.Successful</code></td><td><code>successful</code></td></tr><tr><td><code>PaymentStatus.Pending</code></td><td><code>pending</code></td></tr><tr><td><code>PaymentStatus.Failed</code></td><td><code>failed</code></td></tr><tr><td><code>PaymentStatus.Canceled</code></td><td><code>canceled</code></td></tr><tr><td><code>PaymentStatus.Expired</code></td><td><code>expired</code></td></tr><tr><td><code>PaymentStatus.Unknown</code></td><td><code>unknown</code></td></tr></tbody></table><p><code>PaymentStatus.values</code> lists every status. <code>PaymentStatus.isFinal(status)</code> is <code>false</code> for <code>pending</code> and <code>unknown</code>. <code>resolveStatus(statuses, gatewayStatus)</code> maps a trimmed gateway value through an object and returns <code>&#39;unknown&#39;</code> when it is not listed.</p>',18)])])}const m=t(c,[["render",r]]);export{y as __pageData,m as default};
